async function api(endpoint, body) {
  const response = await fetch(API + endpoint, {
    method: body === undefined ? 'GET' : 'POST',
    headers: body === undefined ? undefined : {'Content-Type': 'application/json'},
    body: body === undefined ? undefined : JSON.stringify(body)
  });
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Request failed');
  return data;
}
async function apiDelete(endpoint) {
  const response = await fetch(API + endpoint, {method: 'DELETE'});
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Request failed');
  return data;
}
const list = id => byId(id).value.split(',').map(x => x.trim()).filter(Boolean);
const number = (id, fallback) => Number(byId(id).value) || fallback;
const numericValue = (id, fallback) => {const value=Number(byId(id).value);return Number.isFinite(value)?value:fallback;};
const clone = value => JSON.parse(JSON.stringify(value));
// A plain <textarea> can only ever hold plain text, so pasted rich text (a
// Word/Google Docs/Gmail bulleted list, say) gets flattened by the browser's
// own HTML-to-plain-text conversion, which drops list markers and often the
// line breaks between items too. Intercepting the paste and doing that
// conversion ourselves keeps bullets, numbering and line breaks intact.
function htmlClipboardToPlainText(html){
  const root=document.createElement('div');
  root.innerHTML=html;
  const BLOCK_TAGS=new Set(['p','div','h1','h2','h3','h4','h5','h6','tr','blockquote']);
  function walk(node,listType,counter){
    let out='';
    node.childNodes.forEach(child=>{
      if(child.nodeType===Node.TEXT_NODE){out+=child.textContent;return;}
      if(child.nodeType!==Node.ELEMENT_NODE)return;
      const tag=child.tagName.toLowerCase();
      if(tag==='li'){
        const marker=listType==='ol'?`${counter.n++}. `:'• ';
        out+=marker+walk(child,null,null).replace(/\s+/g,' ').trim()+'\n';
      }else if(tag==='ul'||tag==='ol'){
        out+=walk(child,tag,{n:1});
      }else if(tag==='br'){
        out+='\n';
      }else if(BLOCK_TAGS.has(tag)){
        const inner=walk(child,listType,counter);
        out+=inner+(inner.trim()?'\n':'');
      }else{
        out+=walk(child,listType,counter);
      }
    });
    return out;
  }
  return walk(root,null,null).replace(/\n{3,}/g,'\n\n').trim();
}
function wireFormattedPaste(textarea){
  textarea.addEventListener('paste',event=>{
    const html=event.clipboardData&&event.clipboardData.getData('text/html');
    if(!html)return;
    const text=htmlClipboardToPlainText(html);
    if(!text)return;
    event.preventDefault();
    const start=textarea.selectionStart,end=textarea.selectionEnd,value=textarea.value;
    textarea.value=value.slice(0,start)+text+value.slice(end);
    const pos=start+text.length;
    textarea.selectionStart=textarea.selectionEnd=pos;
    textarea.dispatchEvent(new Event('input',{bubbles:true}));
  });
}
