function installSetupTooltips(){const tip=document.createElement('div');tip.id='setupTooltip';tip.className='setup-tooltip';document.body.append(tip);const helpNames={applicationWorkAuthorization:'Work authorization',applicationSponsorship:'Sponsorship needs',applicationRelocation:'Relocation preference',applicationTravel:'Travel preference',applicationAdditionalFacts:'Other stable facts',keywords:'Keywords',keywordBank:'Saved keyword bank',blockedWords:'Blocked words',location:'Location',zipCode:'ZIP code',radiusMiles:'Radius miles',salaryMin:'Minimum salary',scoringMethod:'Scoring method',matchThreshold:'Resume-match selectivity',boostTerms:'Boost terms',boostWeight:'Boost influence',searchRemote:'Search remote',searchLocal:'Search local or hybrid',sourceAdzuna:'Adzuna',sourceSerpapi:'SerpAPI',sourceIndeed:'Indeed',adzunaPages:'Adzuna remote pages',adzunaLocalPages:'Adzuna local pages',adzunaResults:'Adzuna results per page',serpapiPages:'SerpAPI remote pages',serpapiLocalPages:'SerpAPI local pages',indeedPages:'Indeed remote pages',indeedLocalPages:'Indeed local pages',indeedResults:'Indeed results per page',resume:'Resume'};Object.entries(setupHelp).forEach(([id,text])=>{const input=byId(id);if(!input)return;const label=input.closest('label');if(!label||label.classList.contains('provider-toggle')||label.querySelector('.info-icon'))return;const icon=document.createElement('button');icon.type='button';icon.className='info-icon';icon.textContent='ⓘ';icon.dataset.tip=text;icon.setAttribute('aria-label','Help for '+helpNames[id]);const fieldName=label.querySelector('.field-name');if(fieldName)fieldName.after(icon);else if(input.type==='checkbox')label.append(icon);else label.insertBefore(icon,input);});document.addEventListener('pointerover',event=>{const icon=event.target.closest&&event.target.closest('.info-icon');if(!icon)return;tip.textContent=icon.dataset.tip;tip.hidden=false;const box=icon.getBoundingClientRect();tip.style.left=Math.max(8,Math.min(box.left,window.innerWidth-tip.offsetWidth-8))+'px';const below=box.bottom+7;tip.style.top=(below+tip.offsetHeight>window.innerHeight-8?Math.max(8,box.top-tip.offsetHeight-7):below)+'px';});document.addEventListener('pointerout',event=>{if(event.target.closest&&event.target.closest('.info-icon'))tip.hidden=true;});document.addEventListener('focusin',event=>{if(event.target.classList&&event.target.classList.contains('info-icon'))event.target.dispatchEvent(new PointerEvent('pointerover',{bubbles:true}));});document.addEventListener('focusout',event=>{if(event.target.classList&&event.target.classList.contains('info-icon'))tip.hidden=true;});}

function setNumericSelectValue(id,value,fallback){const select=byId(id),numeric=Number(value??fallback);select.querySelectorAll('option[data-custom="true"]').forEach(option=>option.remove());let option=[...select.options].find(item=>Math.abs(Number(item.value)-numeric)<1e-9);if(!option){option=new Option(`Custom — ${Math.round(numeric*100)} match-score points`,String(numeric));option.dataset.custom='true';option.dataset.name='Custom';select.add(option);}select.value=option.value;}
function fillCriteria(cfg, resumeText) {
  config = clone(cfg);
  byId('keywords').value = (cfg.keywords || []).join(', ');
  byId('blockedWords').value = (cfg.blocked_words || []).join(', ');
  byId('keywordBank').value = (cfg.____comment_keywords || cfg.saved_keywords || []).join(', ');
  byId('location').value = cfg.location || '';
  byId('zipCode').value = cfg.zip_code || '';
  byId('radiusMiles').value = cfg.radius_miles || 50;
  byId('salaryMin').value = cfg.salary_min || 0;
  byId('scoringMethod').value = cfg.scoring_method || 'semantic';
  setNumericSelectValue('matchThreshold',cfg.match_threshold,.18);
  byId('boostTerms').value = (cfg.boost_terms || []).join(', ');
  setNumericSelectValue('boostWeight',cfg.boost_weight,.15);
  byId('searchRemote').checked = !!cfg.search_remote;
  byId('searchLocal').checked = !!cfg.search_local;
  const sources = cfg.sources || {};
  byId('sourceAdzuna').checked = Object.prototype.hasOwnProperty.call(sources,'adzuna') ? !!sources.adzuna : true;
  byId('sourceSerpapi').checked = Object.prototype.hasOwnProperty.call(sources,'serpapi') ? !!sources.serpapi : true;
  byId('sourceIndeed').checked = !!sources.indeed;
  byId('adzunaPages').value = cfg.adzuna_max_pages || 5;
  byId('adzunaLocalPages').value = cfg.adzuna_local_max_pages || 2;
  byId('adzunaResults').value = cfg.adzuna_results_per_page || 30;
  byId('serpapiPages').value = cfg.serpapi_max_pages || 5;
  byId('serpapiLocalPages').value = cfg.serpapi_local_max_pages || 1;
  byId('indeedPages').value = cfg.indeed_max_pages || 5;
  byId('indeedLocalPages').value = cfg.indeed_local_max_pages || 2;
  byId('indeedResults').value = cfg.indeed_results_per_page || 30;
  byId('resume').value = resumeText || '';
  byId('criteriaSummary').textContent = `${(cfg.keywords || []).join(', ') || 'No keywords'} · ${cfg.location || 'No location'} · ${cfg.search_remote ? 'Remote ' : ''}${cfg.search_local ? 'Local' : ''}`;
  if(byId('searchPresetButtons'))renderSearchPresets();
  updateSetupDependencies();
}

function setDependentControl(id,enabled){const control=byId(id);if(!control)return;control.disabled=!enabled;const label=control.closest('label');if(label)label.classList.toggle('dependency-disabled',!enabled);}
function updateProviderBlocks(){[['sourceSerpapi','serpapiProviderBlock'],['sourceAdzuna','adzunaProviderBlock']].forEach(([sourceId,blockId])=>byId(blockId).classList.toggle('provider-disabled',!byId(sourceId).checked));}
function updateSetupDependencies(){
  const hasBoost=list('boostTerms').length>0, remote=byId('searchRemote').checked, local=byId('searchLocal').checked;
  const adzuna=byId('sourceAdzuna').checked, serpapi=byId('sourceSerpapi').checked, indeed=byId('sourceIndeed').checked;
  setDependentControl('boostWeight',hasBoost);
  ['location','zipCode','radiusMiles'].forEach(id=>setDependentControl(id,local));
  setDependentControl('adzunaPages',adzuna&&remote);setDependentControl('adzunaLocalPages',adzuna&&local);setDependentControl('adzunaResults',adzuna);
  setDependentControl('serpapiPages',serpapi&&remote);setDependentControl('serpapiLocalPages',serpapi&&local);
  setDependentControl('indeedPages',indeed&&remote);setDependentControl('indeedLocalPages',indeed&&local);setDependentControl('indeedResults',indeed);
  updateProviderBlocks();
  updateCreditDisplays();
  updateScoringGuidance();
}

function collectCriteria() {
  Object.assign(config, {
    keywords: list('keywords'), blocked_words: list('blockedWords'), ____comment_keywords: list('keywordBank'),
    location: byId('location').value.trim(), zip_code: byId('zipCode').value.trim(),
    radius_miles: number('radiusMiles', 50), salary_min: number('salaryMin', 0),
    scoring_method: byId('scoringMethod').value, match_threshold: numericValue('matchThreshold', .18),
    boost_terms: list('boostTerms'), boost_weight: numericValue('boostWeight', .15),
    search_remote: byId('searchRemote').checked, search_local: byId('searchLocal').checked,
    sources: {adzuna: byId('sourceAdzuna').checked, serpapi: byId('sourceSerpapi').checked, indeed: byId('sourceIndeed').checked},
    adzuna_max_pages: number('adzunaPages', 1), adzuna_local_max_pages: number('adzunaLocalPages', 1), adzuna_results_per_page: number('adzunaResults', 30),
    serpapi_max_pages: number('serpapiPages', 1), serpapi_local_max_pages: number('serpapiLocalPages', 1),
    indeed_max_pages: number('indeedPages', 1), indeed_local_max_pages: number('indeedLocalPages', 1), indeed_results_per_page: number('indeedResults', 30)
  });
  return config;
}

function activeTargetedEmployerCount(){return employerSources.filter(source=>source.adapter==='serpapi_company'&&source.enabled&&(source.enabled_all_roles||source.enabled_for_role)).length;}
function serpapiEstimate(cfg){const keywords=(cfg.keywords||[]).filter(value=>String(value).trim()).length;if(!(cfg.sources||{}).serpapi)return{total:0,keywords,remote:0,local:0,targeted:0,enabled:false};const remote=cfg.search_remote?Number(cfg.serpapi_max_pages||0)*keywords:0,local=cfg.search_local?Number(cfg.serpapi_local_max_pages||0)*keywords:0;const targetedCount=activeTargetedEmployerCount(),targetedPages=Math.max(1,Math.min(3,Number(cfg.priority_employer_serpapi_max_pages)||1));const targeted=targetedCount?keywords*targetedCount*targetedPages*((cfg.search_remote?1:0)+(cfg.search_local?1:0)):0;return{total:remote+local+targeted,keywords,remote,local,targeted,enabled:true};}
function setupEstimate(){return serpapiEstimate({keywords:list('keywords'),sources:{serpapi:byId('sourceSerpapi').checked},search_remote:byId('searchRemote').checked,search_local:byId('searchLocal').checked,serpapi_max_pages:Number(byId('serpapiPages').value)||0,serpapi_local_max_pages:Number(byId('serpapiLocalPages').value)||0,priority_employer_serpapi_max_pages:config&&config.priority_employer_serpapi_max_pages});}
function creditValue(value){const numeric=Number(value);return Number.isFinite(numeric)?numeric.toLocaleString():String(value??'unknown');}
function renewalDateText(value){if(!value)return'';const parts=String(value).match(/^(\d{4})-(\d{2})-(\d{2})$/);const date=parts?new Date(Number(parts[1]),Number(parts[2])-1,Number(parts[3])):new Date(value);return Number.isNaN(date.getTime())?String(value):date.toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});}
function renewalBalanceText(){if(!serpapiAccount||!serpapiAccount.has_key)return'';const date=renewalDateText(serpapiAccount.plan_renewal_date),allowance=serpapiAccount.searches_per_month==null?'':creditValue(serpapiAccount.searches_per_month);if(!date)return'renewal date unavailable';return`renews ${date}${allowance?` with ${allowance} monthly credits`:''}`;}
function creditBalanceText(){if(!serpapiAccount)return'Checking SerpAPI balance…';if(serpapiAccount.error)return'SerpAPI balance is temporarily unavailable.';if(!serpapiAccount.has_key)return'No active SerpAPI key is stored.';return`${creditValue(serpapiAccount.searches_left)} credits remaining · ${serpapiAccount.plan_name||'plan unknown'} · ${creditValue(serpapiAccount.this_month_usage||0)} used this month · ${renewalBalanceText()}`;}
