function updateScoringGuidance(){if(!byId('scoringRelationshipMessage'))return;const method=byId('scoringMethod').value,threshold=numericValue('matchThreshold',.18),boost=numericValue('boostWeight',.15),terms=list('boostTerms'),thresholdOption=byId('matchThreshold').selectedOptions[0],boostOption=byId('boostWeight').selectedOptions[0];const methodText={semantic:'Semantic meaning recognizes related experience even when the wording differs.',tfidf:'Exact wording emphasizes words and phrases shared by the posting and your resume.',hybrid:'Balanced hybrid combines semantic meaning (60%) with exact shared wording (40%).'}[method]||'The selected method compares each posting with your resume.';const thresholdName=thresholdOption?.dataset.name||'Selected',boostName=boostOption?.dataset.name||'Selected';byId('scoringRelationshipMessage').textContent=`${methodText} ${thresholdName} selectivity keeps jobs whose final score reaches ${Math.round(threshold*100)} match-score points. ${terms.length?`${boostName} boost influence adds ${Math.round(boost*100)} points for each matched boost term before that cutoff.`:'Add comma-separated boost terms if you want preferences to raise a job’s final score.'}`;const scored=(decisionReport?.jobs||[]).filter(entry=>entry.score!==null&&entry.score!==undefined&&Number.isFinite(Number(entry.score)));byId('scoringHistoryContext').textContent=scored.length?`Using the final scores recorded by your latest search, this cutoff would have kept ${scored.filter(entry=>Number(entry.score)>=threshold).length} of ${scored.length} scored jobs. Changing the method or boosts requires a new search to recalculate those scores.`:'After a completed search, this area will show how the selected cutoff compares with your latest recorded job scores.';}
