function markCriteriaSaved(){savedCriteriaForm=captureCriteriaForm();}
function hasUnsavedCriteria(){return savedCriteriaForm!==null&&JSON.stringify(captureCriteriaForm())!==JSON.stringify(savedCriteriaForm);}
