function currentRoleQuery(){const preset=activeSearchPreset();return preset?`preset_id=${encodeURIComponent(preset.id)}`:`role_name=${encodeURIComponent(config&&config.active_search_preset_name||'Default')}`;}
function currentRoleDocument(kind,format){return(setupRoleDocuments&&setupRoleDocuments.documents||[]).find(item=>item.kind===kind&&item.format===format&&item.is_current);}
async function loadSetupRoleDocuments(){const data=await api('role_documents?'+currentRoleQuery());setupRoleDocuments=data;const pdf=currentRoleDocument('resume','pdf'),status=byId('setupRolePdfStatus'),download=byId('downloadSetupRolePdf');status.textContent=pdf?`${data.role.role_name} resume PDF · version ${pdf.version} · saved ${new Date(pdf.created_at+'Z').toLocaleString()}`:`No resume PDF is saved for ${data.role.role_name}. The ATS text remains available for ranking.`;download.hidden=!pdf;if(pdf){download.href=API+`role_documents/${encodeURIComponent(pdf.id)}/download`;download.textContent=`Download PDF v${pdf.version}`;}return data;}
async function uploadRolePdf(file,kind,values){if(!file)throw new Error('Choose a PDF file.');const form=new FormData();form.append('file',file);form.append('kind',kind);Object.entries(values||{}).forEach(([key,value])=>{if(value!==undefined&&value!==null&&value!=='')form.append(key,value);});const response=await fetch(API+'role_documents/upload',{method:'POST',body:form});const data=await response.json();if(!response.ok)throw new Error(data.error||'Upload failed');return data;}
async function uploadSetupRolePdf(){const input=byId('setupRolePdfFile'),preset=activeSearchPreset(),values=preset?{preset_id:preset.id}:{role_name:config&&config.active_search_preset_name||'Default'};try{setupRoleDocuments=await uploadRolePdf(input.files[0],'resume',values);input.value='';await loadSetupRoleDocuments();byId('setupRolePdfMessage').textContent='Role resume PDF saved as the new current version.';}catch(error){byId('setupRolePdfMessage').textContent=error.message||'Could not save the role resume PDF.';}}
async function refreshSearchPresets(){const data=await api('search_presets');searchPresets=data.presets||[];renderSearchPresets();renderApplications();}
async function saveCurrentSearchPreset(){const name=byId('searchPresetName').value.trim(),resumeText=byId('resume').value.trim();if(!name){byId('searchPresetMessage').textContent='Enter a name for this preset.';byId('searchPresetName').focus();return;}if(!resumeText){byId('searchPresetMessage').textContent='A resume is required in every search preset.';byId('resume').focus();return;}const button=byId('saveSearchPreset');button.disabled=true;try{const cfg=collectCriteria(),response=await api('search_presets',{user:identity.profile_key,name,config:cfg,resume:resumeText});cfg.active_search_preset_name=response.preset.name;cfg.active_search_preset_id=response.preset.id;cfg.active_search_preset_color=response.preset.color;savedSnapshot={config:clone(cfg),resume:resumeText};fillCriteria(cfg,resumeText);markCriteriaSaved();await refreshSearchPresets();byId('searchPresetName').value='';byId('searchPresetSaveEditor').hidden=true;await fetchSerpapiStatus();byId('searchPresetMessage').textContent=`${response.preset.name} saved and activated.`;}catch(error){byId('searchPresetMessage').textContent=error.message||'Could not save this search preset.';}finally{button.disabled=false;}}
async function loadSearchPreset(presetId,{skipUnsaved=false}={}){
  if(presetSwitchPending)return false;
  const current=activeSearchPreset();
  if(current&&current.id===Number(presetId)){renderSearchPresets();return true;}
  if(!skipUnsaved&&hasUnsavedCriteria()&&!confirm('Discard unsaved search criteria or resume changes and switch roles?')){renderSearchPresets();return false;}
  presetSwitchPending=true;
  const buttons=[...byId('searchPresetButtons').querySelectorAll('button')];
  buttons.forEach(button=>button.disabled=true);
  byId('runRoleSelect').disabled=true;
  try{
    const response=await api('search_presets/load',{user:identity.profile_key,preset_id:presetId}),preset=response.preset;
    fillCriteria(preset.config,preset.resume);
    savedSnapshot={config:clone(preset.config),resume:preset.resume};
    markCriteriaSaved();
    byId('searchPresetSaveEditor').hidden=true;
    await fetchSerpapiStatus();
    byId('searchPresetMessage').textContent=preset.name+' loaded and activated for the next search.';
    return true;
  }catch(error){
    byId('searchPresetMessage').textContent=error.message||'Could not load this search role.';
    return false;
  }finally{presetSwitchPending=false;renderSearchPresets();}
}
async function deleteActiveSearchPreset(){
  const preset=activeSearchPreset();
  if(!preset)return;
  if(hasUnsavedCriteria()&&!confirm('Discard unsaved search criteria or resume changes before deleting this role?'))return;
  if(!confirm('Delete the saved role “'+preset.name+'”? Tracked jobs keep their saved role labels.'))return;
  const button=byId('deleteSearchPreset');button.disabled=true;
  try{
    await api('search_presets/delete',{user:identity.profile_key,preset_id:preset.id});
    config.active_search_preset_name='Default';
    delete config.active_search_preset_id;delete config.active_search_preset_color;
    savedSnapshot.config.active_search_preset_name='Default';
    delete savedSnapshot.config.active_search_preset_id;delete savedSnapshot.config.active_search_preset_color;
    await refreshSearchPresets();
    const fallback=orderedSearchPresets()[0];
    if(fallback){
      const loaded=await loadSearchPreset(fallback.id,{skipUnsaved:true});
      if(!loaded)return;
    }else markCriteriaSaved();
    byId('searchPresetName').value='';
    byId('searchPresetSaveEditor').hidden=true;
    byId('searchPresetMessage').textContent=preset.name+' deleted.';
  }catch(error){byId('searchPresetMessage').textContent=error.message||'Could not delete this search role.';}
  finally{renderSearchPresets();renderApplications();}
}
