function enrichApplicationRecord(jobId,record){const result=resultForApplication(jobId);['title','company','url','apply_url','source','location','remote_status','salary','score','posted','posted_at','search_role','search_role_color'].forEach(field=>{if((record[field]===undefined||record[field]===null||record[field]==='')&&result[field]!==undefined&&result[field]!==null&&result[field]!=='')record[field]=result[field];});return record;}
function readApplicationFilters(){applicationFilters={work_style:byId('applicationWorkStyle').value,minimum_score:byId('applicationMinimumScore').value,salary:byId('applicationSalary').value,source:byId('applicationSource').value,stage:byId('applicationStage').value,posted:byId('applicationPosted').value};renderApplications();}
