function filteredApplications(entries){const now=Date.now();return entries.filter(([,job])=>{const style=String(job.remote_status||'unclear').toLowerCase();if(applicationRoleTab!=='all'){const role=searchPresets.find(preset=>String(preset.id)===applicationRoleTab);if(!role||String(job.search_role||'').trim().toLocaleLowerCase()!==role.name.trim().toLocaleLowerCase())return false;}if(applicationFilters.work_style&&(applicationFilters.work_style==='local'?!['local','onsite','on-site'].includes(style):style!==applicationFilters.work_style))return false;if(applicationFilters.minimum_score&&hasScore(job)&&Number(job.score)<Number(applicationFilters.minimum_score))return false;if(applicationFilters.salary&&Number(job.salary||0)<Number(applicationFilters.salary))return false;if(applicationFilters.source&&String(job.source||'').toLowerCase()!==applicationFilters.source.toLowerCase())return false;if(applicationFilters.stage&&trackerStage(job)!==applicationFilters.stage)return false;if(applicationFilters.posted){const posted=Date.parse(job.posted||job.posted_at||'');if(!posted||now-posted>Number(applicationFilters.posted)*86400000)return false;}return true;});}
