async function loadApplicationAssistant(selectedId){try{const [profileData,credentialData,attemptData]=await Promise.all([api('application_profile'),api('application_credentials'),api('application_attempts')]);fillApplicationProfile(profileData.profile||{});renderAiProviderCredentials(credentialData.providers||{openai:credentialData.openai});applicationAttempts=attemptData.attempts||[];byId('assistantMetric').textContent=`${applicationAttempts.length} application attempt${applicationAttempts.length===1?'':'s'}`;renderApplicationAttemptList();const id=selectedId||activeApplicationAttemptId;if(id&&applicationAttempts.some(item=>item.id===id))await openApplicationAttempt(id);}catch(error){byId('assistantMetric').textContent='Application assistant unavailable';showActionMessage(error.message||'Could not load the application assistant.');}}
