function artifactGroups(artifacts){const groups=new Map();(artifacts||[]).forEach(artifact=>{const key=`${artifact.kind}:${artifact.version}`;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(artifact);});return [...groups.values()];}
function renderApplicationAttemptDetail(attempt){const root=byId('applicationAttemptDetail');root.hidden=false;root.replaceChildren();const heading=document.createElement('h3');heading.textContent=`${attempt.job.title||'Untitled job'}${attempt.job.company?' — '+attempt.job.company:''}`;const status=document.createElement('p');const badge=document.createElement('span');badge.className='attempt-state';badge.textContent=attempt.state_label;status.append(badge,document.createTextNode(' '+(attempt.status_message||'')));const provenance=document.createElement('p');provenance.className=attempt.automation_used?'automation-flag':'muted';provenance.textContent=attempt.automation_used?'This attempt used assisted browser automation.':'No browser automation has been used for this attempt.';const links=document.createElement('div');links.className='actions';const url=attempt.resolved_url||attempt.source_url;if(url){const link=document.createElement('a');link.className='secondary detail-link';link.href=url;link.target='_blank';link.rel='noopener';link.textContent='Open application page';links.append(link);}root.append(heading,status,provenance,links);if(['queued','awaiting_document_approval','ready_for_review'].includes(attempt.state)){const choice=applicationDocumentChoices[attempt.id]||{ai:false,provider:'openai'};applicationDocumentChoices[attempt.id]=choice;const box=document.createElement('section');box.className='document-choice';const toggleLabel=document.createElement('label');const toggle=document.createElement('input');toggle.type='checkbox';toggle.id='enableAiDocuments';toggle.checked=choice.ai;toggleLabel.append(toggle,document.createTextNode(' Enable AI generation of a tailored resume and cover letter'));const explanation=document.createElement('p');explanation.id='applicationDocumentEstimate';explanation.className='assistant-cost';const controls=document.createElement('div');controls.className='document-choice-controls';const providerLabel=document.createElement('label');providerLabel.textContent='AI provider';const providerSelect=document.createElement('select');providerSelect.id='applicationAiProvider';Object.entries(aiProviderCredentials).forEach(([key,details])=>providerSelect.add(new Option(`${details.label} — ${details.model}${details.is_set?'':' (API key needed)'}`,key)));providerSelect.value=choice.provider in aiProviderCredentials?choice.provider:'openai';providerLabel.append(providerSelect);const action=document.createElement('button');action.className='primary';action.id='applicationDocumentAction';toggle.onchange=async()=>{choice.ai=toggle.checked;await updateDocumentChoice(attempt);};providerSelect.onchange=async()=>{choice.provider=providerSelect.value;await updateDocumentChoice(attempt);};controls.append(providerLabel,action);box.append(toggleLabel,explanation,controls);root.append(box);}const actions=document.createElement('div');actions.className='actions';if(applicationFeatures.preparation_enabled&&['queued','awaiting_document_approval','ready_for_review','needs_user_input','could_not_fill'].includes(attempt.state)){const prepare=document.createElement('button');prepare.className='primary';prepare.textContent='Prepare supported application form';prepare.onclick=()=>runApplicationAction(attempt.id,'prepare');actions.append(prepare);}if(applicationFeatures.submission_enabled&&attempt.state==='ready_for_review'){const submit=document.createElement('button');submit.className='danger';submit.textContent='Review and confirm submission';submit.onclick=()=>confirmApplicationSubmission(attempt);actions.append(submit);}if(!['submitted','cancelled','url_invalid','manual_required','unsupported_site'].includes(attempt.state)){const cancel=document.createElement('button');cancel.className='secondary';cancel.textContent='Cancel attempt';cancel.onclick=()=>runApplicationAction(attempt.id,'cancel');actions.append(cancel);}if(['cancelled','url_invalid','manual_required','unsupported_site','submission_failed','could_not_fill'].includes(attempt.state)){const retry=document.createElement('button');retry.className='secondary';retry.textContent='Start a new attempt';retry.onclick=()=>runApplicationAction(attempt.id,'retry');actions.append(retry);}root.append(actions);if(!applicationFeatures.preparation_enabled){const note=document.createElement('p');note.className='muted';note.textContent='Assisted form preparation and submission are installed but disabled until DEV acceptance. Document preparation and approval are available now.';root.append(note);}const groups=artifactGroups(attempt.artifacts);if(groups.length){const title=document.createElement('h4');title.textContent='Application documents';const list=document.createElement('div');list.className='artifact-list';groups.forEach(group=>{const first=group[0],row=document.createElement('div');row.className='artifact-row';const name=document.createElement('span');name.className='artifact-name';const source=first.provider==='saved_role'?'saved role resume':(first.provider?`${first.provider}${first.model?' · '+first.model:''}`:'');name.textContent=`${first.kind.replaceAll('_',' ')} · version ${first.version} · ${first.approval_state}${source?' · '+source:''}`;row.append(name);group.forEach(artifact=>{const link=document.createElement('a');link.className='secondary detail-link';link.href=API+`application_artifacts/${encodeURIComponent(artifact.id)}/download`;link.textContent=artifact.format.toUpperCase();row.append(link);});if(['resume','cover_letter'].includes(first.kind)&&first.approval_state==='pending'){['approved','rejected'].forEach(decision=>{const button=document.createElement('button');button.className=decision==='approved'?'primary':'secondary';button.textContent=decision==='approved'?'Approve':'Reject';button.onclick=()=>decideApplicationArtifact(first.id,decision);row.append(button);});}list.append(row);});root.append(title,list);const latest=[...new Map((attempt.artifacts||[]).map(item=>[item.version,item])).values()].sort((a,b)=>b.version-a.version)[0];if(latest&&latest.provider&&latest.provider!=='saved_role'){const actual=document.createElement('p');actual.className='assistant-cost';actual.textContent=`Latest AI generation used ${latest.input_tokens.toLocaleString()} input and ${latest.output_tokens.toLocaleString()} output tokens · actual API cost $${Number(latest.actual_cost_usd).toFixed(4)}`;root.append(actual);}}const unanswered=latestUnanswered(attempt);if(unanswered.length){const title=document.createElement('h4');title.textContent='Answers needed';const form=document.createElement('div');form.className='assistant-profile-grid';unanswered.forEach(field=>{const label=document.createElement('label');label.textContent=field.label;const input=document.createElement('textarea');input.dataset.answerLabel=field.label;input.value=attempt.answers&&attempt.answers[field.label]||'';input.placeholder=field.reason.replaceAll('_',' ');label.append(input);form.append(label);});const save=document.createElement('button');save.className='primary';save.textContent='Save these answers';save.onclick=()=>saveApplicationAnswers(attempt.id,form);root.append(title,form,save);}const timelineTitle=document.createElement('h4');timelineTitle.textContent='Progress history';const timeline=document.createElement('ol');timeline.className='attempt-timeline';(attempt.events||[]).forEach(event=>{const item=document.createElement('li');item.textContent=`${new Date(event.created_at+'Z').toLocaleString()} — ${event.state_label}: ${event.message}`;timeline.append(item);});root.append(timelineTitle,timeline);}
async function updateDocumentChoice(attempt){const target=byId('applicationDocumentEstimate'),action=byId('applicationDocumentAction'),providerSelect=byId('applicationAiProvider');if(!target||!action)return;const choice=applicationDocumentChoices[attempt.id]||{ai:false,provider:'openai'};providerSelect.disabled=!choice.ai;action.textContent=choice.ai?(attempt.artifacts&&attempt.artifacts.length?'Generate revised AI documents':'Generate tailored resume + cover letter'):`Use saved ${attempt.job.search_role||'Default'} role resume`;if(!choice.ai){delete target.dataset.cost;target.textContent=`Default: use the resume saved with the “${attempt.job.search_role||'Default'}” role. It will not be sent to an AI provider.`;action.onclick=()=>useSavedApplicationResume(attempt.id);return;}const details=aiProviderCredentials[choice.provider];action.disabled=!(details&&details.is_set);action.onclick=()=>generateApplicationDocuments(attempt.id,choice.provider);target.textContent='Calculating AI document estimate…';try{const data=await api(`application_attempts/${encodeURIComponent(attempt.id)}/documents/estimate?provider=${encodeURIComponent(choice.provider)}`);const estimate=data.estimate;target.dataset.cost=estimate.estimated_cost_usd;target.textContent=`${estimate.provider_label} (${estimate.model}) estimate: about ${estimate.estimated_input_tokens.toLocaleString()} input + ${estimate.estimated_output_tokens.toLocaleString()} output tokens · $${Number(estimate.estimated_cost_usd).toFixed(4)}. Source resume: ${data.role_name}.`;action.disabled=!(details&&details.is_set);}catch(error){target.textContent=error.message||'Document estimate unavailable.';action.disabled=true;}}
async function useSavedApplicationResume(attemptId){if(!confirm('Use the resume saved with this job’s originating role? No AI service will receive it.'))return;try{showNotice('Loading saved role resume…');const response=await api(`application_attempts/${encodeURIComponent(attemptId)}/documents/use-saved`,{});await loadApplicationAssistant(response.attempt.id);}catch(error){showActionMessage(error.message||'Could not load the saved role resume.');await openApplicationAttempt(attemptId);}}
async function generateApplicationDocuments(attemptId,provider){const estimate=byId('applicationDocumentEstimate'),cost=estimate&&estimate.dataset.cost,details=aiProviderCredentials[provider];if(!confirm(`Generate a tailored resume and cover letter with ${details?details.label:provider}${cost?` (estimated maximum $${Number(cost).toFixed(4)})`:''}? You will review and approve them before use.`))return;try{showNotice('Generating documents…');const response=await api(`application_attempts/${encodeURIComponent(attemptId)}/documents/generate`,{provider});renderApplicationAttemptDetail(response.attempt);await loadApplicationAssistant(attemptId);}catch(error){showActionMessage(error.message||'Could not generate documents.');await openApplicationAttempt(attemptId);}}
function rolePdfDocuments(kind){return(activeAttemptRoleDocuments&&activeAttemptRoleDocuments.documents||[]).filter(item=>item.kind===kind&&item.format==='pdf');}
function prepareDocumentSelectionUI(attempt){const root=byId('applicationAttemptDetail'),aiBox=root.querySelector('.document-choice');const applicationLink=[...root.querySelectorAll('a.detail-link')].find(link=>link.textContent==='Open application page');if(applicationLink)applicationLink.textContent=attempt.application_url_kind==='job_listing'?'Open available job listing':'Open application page';if(!aiBox)return;const choice=applicationDocumentChoices[attempt.id]||{ai:false,provider:'openai',resume:true,cover:true};if(choice.resume===undefined)choice.resume=true;if(choice.cover===undefined)choice.cover=true;applicationDocumentChoices[attempt.id]=choice;const saved=document.createElement('section');saved.className='saved-document-box';const heading=document.createElement('h4');heading.textContent=`Use documents saved with role: ${activeAttemptRoleDocuments&&activeAttemptRoleDocuments.role.role_name||attempt.job.search_role||'Default'}`;const help=document.createElement('p');help.className='muted';help.textContent='These choices are separate from AI generation. Selecting them copies the exact files into this application’s permanent history.';const controls=document.createElement('div');controls.className='document-choice-controls';const resumeLabel=document.createElement('label');resumeLabel.textContent='Resume PDF';const resumeSelect=document.createElement('select');resumeSelect.id='savedResumeDocument';const resumePdfs=rolePdfDocuments('resume');resumeSelect.add(new Option(resumePdfs.length?'Use current resume PDF':'Build PDF from saved ATS text',''));resumePdfs.forEach(item=>{const option=new Option(`${item.is_current?'Current · ':''}PDF version ${item.version} · ${new Date(item.created_at+'Z').toLocaleDateString()}`,item.id);option.selected=!!item.is_current;resumeSelect.add(option);});resumeLabel.append(resumeSelect);const coverLabel=document.createElement('label');coverLabel.textContent='Cover letter PDF (optional)';const coverSelect=document.createElement('select');coverSelect.id='savedCoverDocument';coverSelect.add(new Option('No saved cover letter',''));rolePdfDocuments('cover_letter').forEach(item=>{const option=new Option(`${item.is_current?'Current · ':''}PDF version ${item.version} · ${new Date(item.created_at+'Z').toLocaleDateString()}`,item.id);option.selected=!!item.is_current;coverSelect.add(option);});coverLabel.append(coverSelect);const use=document.createElement('button');use.className='primary';use.textContent='Use selected saved documents';use.onclick=()=>useSavedApplicationResume(attempt.id);controls.append(resumeLabel,coverLabel,use);const uploads=document.createElement('div');uploads.className='role-document-row';const resumeUpload=document.createElement('label');resumeUpload.textContent='Replace role resume PDF';const resumeFile=document.createElement('input');resumeFile.type='file';resumeFile.accept='application/pdf,.pdf';resumeUpload.append(resumeFile);const resumeButton=document.createElement('button');resumeButton.className='secondary';resumeButton.textContent='Upload replacement';resumeButton.onclick=()=>uploadAttemptRolePdf(attempt.id,'resume',resumeFile);const coverUpload=document.createElement('label');coverUpload.textContent='Replace role cover letter PDF';const coverFile=document.createElement('input');coverFile.type='file';coverFile.accept='application/pdf,.pdf';coverUpload.append(coverFile);const coverButton=document.createElement('button');coverButton.className='secondary';coverButton.textContent='Upload replacement';coverButton.onclick=()=>uploadAttemptRolePdf(attempt.id,'cover_letter',coverFile);uploads.append(resumeUpload,resumeButton,coverUpload,coverButton);saved.append(heading,help,controls,uploads);aiBox.before(saved);const toggle=byId('enableAiDocuments');toggle.nextSibling.textContent=' Enable AI document generation';const sub=document.createElement('div');sub.className='ai-subchoices';sub.id='applicationAiKinds';const resumeChoice=document.createElement('label'),resumeCheck=document.createElement('input');resumeCheck.type='checkbox';resumeCheck.checked=choice.resume;resumeChoice.append(resumeCheck,document.createTextNode(' Generate resume'));const coverChoice=document.createElement('label'),coverCheck=document.createElement('input');coverCheck.type='checkbox';coverCheck.checked=choice.cover;coverChoice.append(coverCheck,document.createTextNode(' Generate cover letter'));resumeCheck.onchange=async()=>{choice.resume=resumeCheck.checked;await updateDocumentChoice(attempt);};coverCheck.onchange=async()=>{choice.cover=coverCheck.checked;await updateDocumentChoice(attempt);};sub.append(resumeChoice,coverChoice);toggle.closest('label').after(sub);const groups=artifactGroups(attempt.artifacts),rows=[...root.querySelectorAll('.artifact-row')];groups.forEach((group,index)=>{const first=group[0],row=rows[index];if(!row)return;if(group.some(item=>item.selected_for_submission)){const selected=document.createElement('span');selected.className='attempt-state';selected.textContent='Selected for this application';row.append(selected);}if(['resume','cover_letter'].includes(first.kind)&&first.approval_state==='approved'&&first.provider&&first.provider!=='saved_role'){const replace=document.createElement('button');replace.className='secondary';replace.textContent=`Replace role ${first.kind==='resume'?'resume':'cover letter'} with this version`;replace.onclick=()=>saveGeneratedToRole(first.id,attempt.id);row.append(replace);}});}
async function uploadAttemptRolePdf(attemptId,kind,input){try{await uploadRolePdf(input.files[0],kind,{attempt_id:attemptId});input.value='';showNotice(`Role ${kind.replace('_',' ')} PDF replaced.`);await openApplicationAttempt(attemptId);}catch(error){showActionMessage(error.message||'Could not replace the role document.');}}
async function saveGeneratedToRole(artifactId,attemptId){if(!confirm('Make this approved AI-generated version the current default for this role? Older versions will remain available.'))return;try{await api(`application_artifacts/${encodeURIComponent(artifactId)}/save-to-role`,{});showNotice('Generated document saved as the role’s current version.');await openApplicationAttempt(attemptId);}catch(error){showActionMessage(error.message||'Could not save this version to the role.');}}
async function updateDocumentChoice(attempt){const target=byId('applicationDocumentEstimate'),action=byId('applicationDocumentAction'),providerSelect=byId('applicationAiProvider'),sub=byId('applicationAiKinds');if(!target||!action)return;const choice=applicationDocumentChoices[attempt.id]||{ai:false,provider:'openai',resume:true,cover:true};providerSelect.disabled=!choice.ai;providerSelect.closest('.document-choice-controls').hidden=!choice.ai;if(sub)sub.hidden=!choice.ai;action.textContent=attempt.artifacts&&attempt.artifacts.length?'Generate revised AI documents':'Generate selected AI documents';if(!choice.ai){delete target.dataset.cost;target.textContent='AI generation is off. Use the separate saved-document section above, or enable AI here.';return;}if(!choice.resume&&!choice.cover){delete target.dataset.cost;target.textContent='Select resume, cover letter, or both.';action.disabled=true;return;}const details=aiProviderCredentials[choice.provider];action.disabled=!(details&&details.is_set);action.onclick=()=>generateApplicationDocuments(attempt.id,choice.provider);target.textContent='Calculating AI document estimate…';try{const query=`provider=${encodeURIComponent(choice.provider)}&resume=${choice.resume?'1':'0'}&cover_letter=${choice.cover?'1':'0'}`;const data=await api(`application_attempts/${encodeURIComponent(attempt.id)}/documents/estimate?${query}`);const estimate=data.estimate;target.dataset.cost=estimate.estimated_cost_usd;target.textContent=`${estimate.provider_label} (${estimate.model}) ${estimate.generated_documents.join(' + ')} estimate: about ${estimate.estimated_input_tokens.toLocaleString()} input + ${estimate.estimated_output_tokens.toLocaleString()} output tokens · $${Number(estimate.estimated_cost_usd).toFixed(4)}. Source resume: ${data.role_name}.`;action.disabled=!(details&&details.is_set);}catch(error){target.textContent=error.message||'Document estimate unavailable.';action.disabled=true;}}
async function useSavedApplicationResume(attemptId){const resume=byId('savedResumeDocument'),cover=byId('savedCoverDocument');if(!confirm('Copy the selected saved role documents into this application’s permanent history? No AI service will receive them.'))return;try{showNotice('Copying saved role documents…');const response=await api(`application_attempts/${encodeURIComponent(attemptId)}/documents/use-saved`,{resume_document_id:resume&&resume.value||null,cover_document_id:cover&&cover.value||null});await loadApplicationAssistant(response.attempt.id);}catch(error){showActionMessage(error.message||'Could not use the saved role documents.');await openApplicationAttempt(attemptId);}}
async function generateApplicationDocuments(attemptId,provider){const choice=applicationDocumentChoices[attemptId]||{resume:true,cover:true},estimate=byId('applicationDocumentEstimate'),cost=estimate&&estimate.dataset.cost,details=aiProviderCredentials[provider],names=[choice.resume?'resume':'',choice.cover?'cover letter':''].filter(Boolean).join(' and ');if(!confirm(`Generate ${names} with ${details?details.label:provider}${cost?` (estimated maximum $${Number(cost).toFixed(4)})`:''}? You will review and approve generated files before use.`))return;try{showNotice('Generating documents…');const response=await api(`application_attempts/${encodeURIComponent(attemptId)}/documents/generate`,{provider,generate_resume:!!choice.resume,generate_cover_letter:!!choice.cover});await loadApplicationAssistant(response.attempt.id);}catch(error){showActionMessage(error.message||'Could not generate documents.');await openApplicationAttempt(attemptId);}}
async function decideApplicationArtifact(artifactId,decision){try{const response=await api(`application_artifacts/${encodeURIComponent(artifactId)}/decision`,{decision});renderApplicationAttemptDetail(response.attempt);await loadApplicationAssistant(response.attempt.id);}catch(error){showActionMessage(error.message||'Could not save the document decision.');}}
async function saveApplicationAnswers(attemptId,form){const answers={};form.querySelectorAll('[data-answer-label]').forEach(input=>answers[input.dataset.answerLabel]=input.value.trim());try{const response=await api(`application_attempts/${encodeURIComponent(attemptId)}/answers`,{answers});renderApplicationAttemptDetail(response.attempt);showNotice('Application answers saved.');}catch(error){showActionMessage(error.message||'Could not save answers.');}}
async function runApplicationAction(attemptId,action){try{const response=await api(`application_attempts/${encodeURIComponent(attemptId)}/${action}`,{});const next=response.attempt;await loadApplicationAssistant(next.id);showNotice(next.status_message||'Application attempt updated.');}catch(error){showActionMessage(error.message||`Could not ${action} the application.`);await openApplicationAttempt(attemptId);}}
async function confirmApplicationSubmission(attempt){const documents=(attempt.artifacts||[]).filter(item=>item.approval_state==='approved').map(item=>item.file_name);const message=`Submit this application now?\n\nJob: ${attempt.job.title||''} — ${attempt.job.company||''}\nDestination: ${attempt.resolved_url||attempt.source_url||''}\nApproved files: ${documents.join(', ')||'none'}\n\nThis is the final confirmation and may create a real application.`;if(!confirm(message))return;try{const confirmation=await api(`application_attempts/${encodeURIComponent(attempt.id)}/confirmation-token`,{});const response=await api(`application_attempts/${encodeURIComponent(attempt.id)}/submit`,{confirmation_token:confirmation.confirmation_token});renderApplicationAttemptDetail(response.attempt);await loadApplicationAssistant(attempt.id);}catch(error){showActionMessage(error.message||'Application submission failed.');await openApplicationAttempt(attempt.id);}}
async function poll(testMode){const data=await api('job_status',{user:identity.profile_key,test_mode:testMode});byId('runStatus').textContent=data.status.message||data.status.state;if(['complete','error','cancelled'].includes(data.status.state)){clearInterval(pollTimer);byId('cancelRun').hidden=true;await Promise.all([loadResults(),loadDecisionReport(),fetchSerpapiStatus()]);}}
async function startRun(testMode){const estimate=serpapiEstimate(config);if(!testMode&&!confirm(`Start a live search? Current settings are estimated to use about ${estimate.total} SerpAPI credit${estimate.total===1?'':'s'}.`))return;try{await api('run',{user:identity.profile_key,test_mode:testMode});byId('runStatus').textContent=testMode?'No-credit test started.':'Live search started.';byId('cancelRun').hidden=false;byId('cancelRun').onclick=()=>api('cancel',{user:identity.profile_key,test_mode:testMode});clearInterval(pollTimer);pollTimer=setInterval(()=>poll(testMode),3000);}catch(error){byId('runStatus').textContent=error.message||'Could not start the search.';}}

function showDashboard(updateHistory=true){document.querySelector('.topbar').hidden=false;document.querySelector('.dashboard').hidden=false;document.querySelectorAll('.workspace').forEach(panel=>panel.hidden=true);window.scrollTo({top:0,behavior:'instant'});if(updateHistory)history.pushState({screen:'dashboard'},'',location.pathname+location.search);}
function setSettingsBackLabel(returnTo){document.querySelectorAll('#settingsPanel .dashboard-back').forEach(button=>button.textContent=returnTo==='runPanel'?'← Back to run a new search':'← Back to dashboard');}
function openWorkspace(id,updateHistory=true,returnTo='dashboard'){document.querySelector('.topbar').hidden=true;document.querySelector('.dashboard').hidden=true;document.querySelectorAll('.workspace').forEach(panel=>panel.hidden=panel.id!==id);if(id==='settingsPanel')setSettingsBackLabel(returnTo);if(id==='applicationsPanel'&&returnTo==='dashboard'){applicationRoleTab='all';renderApplications();}window.scrollTo({top:0,behavior:'instant'});if(updateHistory)history.pushState({screen:id,returnTo},'',`#${id}`);}
function editSearchSetupFromRun(){openWorkspace('settingsPanel',true,'runPanel');}
let onboardingStep=0;
function showOnboardingStep(step){onboardingStep=step;document.querySelectorAll('[data-onboarding-step]').forEach(panel=>panel.hidden=Number(panel.dataset.onboardingStep)!==step);byId('onboardingProgress').textContent=step===0?'Getting started':`Step ${step} of 9`;byId('onboardingNav').hidden=step===0;byId('onboardingBack').hidden=step===1;byId('onboardingNext').textContent=step===9?'Save my setup':'Continue';byId('onboardingError').textContent='';if(step===9)renderOnboardingReview();const field=document.querySelector(`[data-onboarding-step="${step}"] input, [data-onboarding-step="${step}"] textarea`);if(field)setTimeout(()=>field.focus(),0);}
function hasStoredCredential(service){return(credentialSummary[service]||[]).some(item=>service==='serpapi'?item.key_mask&&item.key_mask!=='Not set':item.app_id_mask&&item.app_id_mask!=='Not set'&&item.app_key_mask&&item.app_key_mask!=='Not set');}
function updateOnboardingSourceDependencies(){const adzuna=byId('onboardingUseAdzuna').checked,serpapi=byId('onboardingUseSerpapi').checked;['onboardingAdzunaId','onboardingAdzunaKey'].forEach(id=>{byId(id).disabled=!adzuna;byId(id).closest('label').classList.toggle('dependency-disabled',!adzuna);});byId('onboardingSerpapiKey').disabled=!serpapi;byId('onboardingSerpapiKey').closest('label').classList.toggle('dependency-disabled',!serpapi);}
function openOnboarding(){byId('onboardingKeywords').value=(config.keywords||[]).join(', ');byId('onboardingRemote').checked=!!config.search_remote;byId('onboardingLocal').checked=!!config.search_local;byId('onboardingLocation').value=config.location||'';byId('onboardingZip').value=config.zip_code||'';byId('onboardingRadius').value=config.radius_miles||50;byId('onboardingSalary').value=config.salary_min||0;byId('onboardingResume').value='';const sources=config.sources||{};byId('onboardingUseAdzuna').checked=!!sources.adzuna;byId('onboardingUseSerpapi').checked=!!sources.serpapi;byId('onboardingUseIndeed').checked=!!sources.indeed;byId('onboardingAdzunaId').value='';byId('onboardingAdzunaKey').value='';byId('onboardingSerpapiKey').value='';byId('onboardingAdzunaId').placeholder=hasStoredCredential('adzuna')?'Existing App ID will be kept':'Paste App ID';byId('onboardingAdzunaKey').placeholder=hasStoredCredential('adzuna')?'Existing App Key will be kept':'Paste App Key';byId('onboardingSerpapiKey').placeholder=hasStoredCredential('serpapi')?'Existing key will be kept':'Paste API key';updateOnboardingSourceDependencies();byId('onboarding').hidden=false;showOnboardingStep(0);}
function validateOnboardingStep(step){const local=byId('onboardingLocal').checked;if(step===1&&!byId('onboardingKeywords').value.split(',').some(value=>value.trim()))return'Enter at least one target role or keyword.';if(step===2&&!byId('onboardingRemote').checked&&!local)return'Select remote jobs, local jobs, or both.';if(step===3&&local&&!byId('onboardingLocation').value.trim())return'Enter the area to use for local searches.';if(step===4&&local&&!/^\d{5}(?:-\d{4})?$/.test(byId('onboardingZip').value.trim()))return'Enter a five-digit ZIP code for local distance filtering.';if(step===5&&local&&Number(byId('onboardingRadius').value)<1)return'Enter a travel radius of at least one mile.';if(step===6&&Number(byId('onboardingSalary').value)<0)return'Minimum salary cannot be negative.';if(step===7&&!byId('onboardingResume').value.trim())return'Paste your resume text so jobs can be ranked for you.';if(step===8&&byId('onboardingUseAdzuna').checked&&!hasStoredCredential('adzuna')&&(!byId('onboardingAdzunaId').value.trim()||!byId('onboardingAdzunaKey').value.trim()))return'Adzuna needs both an App ID and App Key. Add them, or turn Adzuna off for now.';if(step===8&&byId('onboardingUseSerpapi').checked&&!hasStoredCredential('serpapi')&&!byId('onboardingSerpapiKey').value.trim())return'SerpAPI needs an API key. Add it, or turn SerpAPI off for now.';return'';}
function renderOnboardingReview(){const roles=byId('onboardingKeywords').value.split(',').map(value=>value.trim()).filter(Boolean);const styles=[byId('onboardingRemote').checked?'Remote':'',byId('onboardingLocal').checked?'Local / hybrid':''].filter(Boolean).join(' and ');const location=byId('onboardingLocal').checked?`${byId('onboardingLocation').value.trim()} · ${byId('onboardingZip').value.trim()} · ${byId('onboardingRadius').value} miles`:'Not needed for remote-only search';const salary=Number(byId('onboardingSalary').value),sources=[byId('onboardingUseAdzuna').checked?'Adzuna':'',byId('onboardingUseSerpapi').checked?'SerpAPI':'',byId('onboardingUseIndeed').checked?'Indeed (experimental)':''].filter(Boolean);byId('onboardingReview').replaceChildren();[['Target roles',roles.join(', ')],['Work style',styles],['Local area',location],['Minimum salary',salary?'$'+salary.toLocaleString():'No minimum'],['Resume','Added'],['Live sources',sources.join(', ')||'None yet — sample test only']].forEach(([label,value])=>{const row=document.createElement('div');const strong=document.createElement('strong');strong.textContent=label+': ';row.append(strong,document.createTextNode(value));byId('onboardingReview').append(row);});}
function onboardingCredentialPayload(){const serpapi=collectCredentials('serpapi'),adzuna=collectCredentials('adzuna'),serpKey=byId('onboardingSerpapiKey').value.trim(),adzunaId=byId('onboardingAdzunaId').value.trim(),adzunaKey=byId('onboardingAdzunaKey').value.trim();if(serpKey){let active=serpapi.find(item=>item.name.toLowerCase()==='active');if(!active){active={name:'Active'};serpapi.push(active);}active.key=serpKey;}if(adzunaId||adzunaKey){let active=adzuna.find(item=>item.name.toLowerCase()==='active');if(!active){active={name:'Active'};adzuna.push(active);}active.app_id=adzunaId;active.app_key=adzunaKey;}return{serpapi,adzuna};}
async function finishOnboarding(){const next=clone(config);next.keywords=byId('onboardingKeywords').value.split(',').map(value=>value.trim()).filter(Boolean);next.search_remote=byId('onboardingRemote').checked;next.search_local=byId('onboardingLocal').checked;next.remote=next.search_remote;next.location=byId('onboardingLocation').value.trim();next.zip_code=byId('onboardingZip').value.trim();next.radius_miles=Number(byId('onboardingRadius').value)||50;next.salary_min=Number(byId('onboardingSalary').value)||0;next.sources={adzuna:byId('onboardingUseAdzuna').checked,serpapi:byId('onboardingUseSerpapi').checked,indeed:byId('onboardingUseIndeed').checked};const resumeText=byId('onboardingResume').value.trim();byId('onboardingNext').disabled=true;try{await api('save',{config:next});await api('resume',{text:resumeText});await api('credentials',{credentials:onboardingCredentialPayload()});await api('onboarding',{state:'complete'});config=next;savedSnapshot={config:clone(next),resume:resumeText};fillCriteria(next,resumeText);markCriteriaSaved();renderCredentials(await api('credentials'));byId('onboarding').hidden=true;byId('runStatus').textContent='Initial setup saved. Try the built-in no-credit test when you are ready.';}catch(error){byId('onboardingError').textContent=error.message||'Could not save setup.';}finally{byId('onboardingNext').disabled=false;}}
async function skipOnboarding(){byId('skipOnboarding').disabled=true;try{await api('onboarding',{state:'dismissed'});byId('onboarding').hidden=true;showDashboard(false);}catch(error){byId('onboardingError').textContent=error.message||'Could not skip setup.';}finally{byId('skipOnboarding').disabled=false;}}
async function init(){try{const [me,cfg,resumeData,creds,presets]=await Promise.all([api('me'),api('load_config'),api('resume'),api('credentials'),api('search_presets')]);identity=me.user;searchPresets=presets.presets||[];let initialConfig=cfg.config,initialResume=resumeData.text;const configuredPreset=searchPresetByName(initialConfig&&initialConfig.active_search_preset_name);if(searchPresets.length&&!configuredPreset){const fallback=mostRecentSearchPreset(),response=await api('search_presets/load',{user:identity.profile_key,preset_id:fallback.id});initialConfig=response.preset.config;initialResume=response.preset.resume;}byId('title').textContent=identity.display_name+"'s JobSearch portal";byId('subtitle').textContent=identity.email;fillCriteria(initialConfig,initialResume);savedSnapshot={config:clone(initialConfig),resume:initialResume};renderCredentials(creds);markCriteriaSaved();renderSearchPresets();await Promise.all([loadResults(),loadApplications(),loadDecisionReport(),fetchSerpapiStatus(),loadApplicationAssistant()]);if(identity.onboarding_state==='pending')openOnboarding();}catch(error){if(error.message==='Sign in required')location=PREFIX+'/login';else byId('runStatus').textContent=error.message;}}
