document.querySelectorAll('.workspace').forEach(panel=>{if(!panel.querySelector('.workspace-footer')){const footer=document.createElement('div');footer.className='workspace-footer';footer.innerHTML='<button class="secondary dashboard-back">← Back to dashboard</button>';panel.append(footer);}});
