function showSettingsTab(name){const criteria=name==='criteria',criteriaTab=byId('toggleCriteria'),credentialsTab=byId('toggleCredentials');byId('criteriaPanel').hidden=!criteria;byId('credentialsPanel').hidden=criteria;criteriaTab.classList.toggle('active-tab',criteria);credentialsTab.classList.toggle('active-tab',!criteria);criteriaTab.setAttribute('aria-selected',String(criteria));credentialsTab.setAttribute('aria-selected',String(!criteria));}
