byId('saveCriteria').onclick=async()=>{try{const cfg=collectCriteria(),resumeText=byId('resume').value.trim(),preset=activeSearchPreset();if(!resumeText)throw new Error('Resume is required.');if(preset){const response=await api('search_presets',{user:identity.profile_key,name:preset.name,config:cfg,resume:resumeText});cfg.active_search_preset_name=response.preset.name;cfg.active_search_preset_id=response.preset.id;cfg.active_search_preset_color=response.preset.color;await refreshSearchPresets();}else{await api('save',{user:identity.profile_key,config:cfg});await api('resume',{user:identity.profile_key,text:resumeText});}savedSnapshot={config:clone(cfg),resume:resumeText};fillCriteria(cfg,resumeText);markCriteriaSaved();await fetchSerpapiStatus();byId('criteriaMessage').textContent=preset?`${preset.name} criteria and resume saved.`:'Criteria saved.';}catch(e){byId('criteriaMessage').textContent=e.message;}};
function nextCredentialName(service){const names=[...byId(`${service}Credentials`).querySelectorAll('.credential-row')].map(row=>(row.querySelector('.credential-name')?.value||row.dataset.name||'').toLowerCase());if(!names.includes('active'))return 'Active';let number=1,name='Spare';while(names.includes(name.toLowerCase()))name=`Spare ${++number}`;return name;}
byId('addSerpapi').onclick=()=>byId('serpapiCredentials').append(credentialRow('serpapi',{name:nextCredentialName('serpapi')},true));
