byId('showSaveSearchPreset').onclick=()=>{const active=activeSearchPreset();byId('searchPresetName').value=active?active.name:'';byId('searchPresetSaveEditor').hidden=false;byId('searchPresetName').focus();};byId('cancelSaveSearchPreset').onclick=()=>{byId('searchPresetSaveEditor').hidden=true;byId('searchPresetName').value='';};byId('saveSearchPreset').onclick=saveCurrentSearchPreset;byId('deleteSearchPreset').onclick=deleteActiveSearchPreset;
