byId('testRun').onclick=()=>startRun(true);byId('liveRun').onclick=()=>startRun(false);byId('runRoleSelect').onchange=()=>loadSearchPreset(Number(byId('runRoleSelect').value));byId('logout').onclick=async()=>{await api('logout',{});location=PREFIX+'/login'};ensureInteractiveFields();['boostTerms','searchRemote','searchLocal','sourceAdzuna','sourceSerpapi','sourceIndeed'].forEach(id=>byId(id).addEventListener('input',updateSetupDependencies));['scoringMethod','matchThreshold','boostWeight'].forEach(id=>byId(id).addEventListener('input',updateScoringGuidance));installSetupTooltips();wireManualJob();init();
